exercise.referenceSolution:
class Identified { int id_; public: explicit Identified(int id) : id_(id) {} int id() const { return id_; } };
class Derived : public Identified { int value_; public: Derived(int id,int value) : Identified(id), value_(value) {} int total() const { return id()+value_; } };
int solve(int a,int b) { return Derived{a,b}.total(); }
